# c19 総力戦 - キャンペーン第19作戦。最大規模の決戦。
#
# **敵の初期配置は自軍と同数（24）**。.cpn の enemy_scale=200 /
# enemy_waves=2 が、開幕に自軍の展開数まで敵を足し、超過分を
# 2・3ターン目に分けて届ける。マップ側の敵が自軍より多いと減らせない。
# 自軍24＋持越し48＝72 で出撃すると、敵は最終的に144になる。
#
# 地形は陸・海・空の全部を使う。南に一本つながった海（艦隊）、
# 中央に南北の山脈（越えられるのは3か所）、両軍に飛行場。
# 自軍は西、敵首都は東。キャンペーンなので回転対称ではない。
[map]
name             = 総力戦
width            = 60
height           = 44
turns            = 60
timeout_winner   = -1
funds0           = 6000
funds1           = 9000

